<template><div class="task-page"><div class="growth-cards"><el-card><el-statistic title="学习计划" :value="stats?.planCount||0"/></el-card><el-card><el-statistic title="进行中" :value="stats?.inProgressCount||0"/></el-card><el-card><el-statistic title="已完成" :value="stats?.completedCount||0"/></el-card><el-card><el-statistic title="学习总时长" :value="stats?.totalMinutes||0" suffix="分钟"/></el-card></div><el-row :gutter="16"><el-col :span="10"><el-card><template #header>主题分布</template><div v-for="(count,topic) in stats?.topicDistribution" :key="topic" class="topic-row"><span>{{topic}}</span><el-progress :percentage="topicPercent(count)" :format="()=>`${count} 个计划`"/></div><el-empty v-if="!Object.keys(stats?.topicDistribution||{}).length" description="暂无主题数据"/></el-card></el-col><el-col :span="14"><el-card><template #header>成长时间线</template><el-timeline><el-timeline-item v-for="r in stats?.recentRecords" :key="`r${r.id}`" :timestamp="format(r.recordTime)">{{r.content}}（{{r.durationMinutes}} 分钟）</el-timeline-item><el-timeline-item v-for="s in stats?.recentSummaries" :key="`s${s.id}`" :timestamp="s.periodEnd" type="success">完成一篇{{summaryType(s.summaryType)}}</el-timeline-item></el-timeline><el-empty v-if="!stats?.recentRecords.length&&!stats?.recentSummaries.length" description="开始学习后，这里会留下成长轨迹"/></el-card></el-col></el-row></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{getGrowthStats,type GrowthStats}from'@/api/learning';const stats=ref<GrowthStats>();function topicPercent(v:number){return Math.round(v/Math.max(stats.value?.planCount||1,1)*100);}function format(v:string){return new Date(v).toLocaleString('zh-CN');}function summaryType(v:string){return({WEEKLY:'周总结',MONTHLY:'月总结',STAGE:'阶段总结'} as Record<string,string>)[v]||'总结';}onMounted(async()=>{stats.value=(await getGrowthStats()).data;});</script>